const upsertCartItem = `-- name: UpsertCartItem :one
INSERT INTO procurement_cart_items (cart_id, org_id, product_id, supplier_org_id, product_name, quantity, unit, unit_price_minor, currency)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (cart_id, product_id)
DO UPDATE SET quantity = procurement_cart_items.quantity + EXCLUDED.quantity, updated_at = now()
RETURNING cart_item_id, cart_id, org_id, product_id, supplier_org_id, product_name, quantity, unit, unit_price_minor, currency, created_at, updated_at
`

type UpsertCartItemParams struct {
	CartID         uuid.UUID `json:"cart_id"`
	OrgID          uuid.UUID `json:"org_id"`
	ProductID      uuid.UUID `json:"product_id"`
	SupplierOrgID  uuid.UUID `json:"supplier_org_id"`
	ProductName    string    `json:"product_name"`
	Quantity       int32     `json:"quantity"`
	Unit           string    `json:"unit"`
	UnitPriceMinor int64     `json:"unit_price_minor"`
	Currency       string    `json:"currency"`
}

// Add a product to the cart or merge quantities (same active product added
// twice merges at the original price snapshot).
func (q *Queries) UpsertCartItem(ctx context.Context, arg UpsertCartItemParams) (ProcurementCartItem, error) {
	row := q.db.QueryRow(ctx, upsertCartItem,
		arg.CartID,
		arg.OrgID,
		arg.ProductID,
		arg.SupplierOrgID,
		arg.ProductName,
		arg.Quantity,
		arg.Unit,
		arg.UnitPriceMinor,
		arg.Currency,
	)
	var i ProcurementCartItem
	err := row.Scan(
		&i.CartItemID,
		&i.CartID,
		&i.OrgID,
		&i.ProductID,
		&i.SupplierOrgID,
		&i.ProductName,
		&i.Quantity,
		&i.Unit,
		&i.UnitPriceMinor,
		&i.Currency,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
